'use strict';
// Local visual prototype; no network calls, storage, notifications, or real AI.
const assetRoot='../../../android/app/src/main/res/drawable-nodpi/';
const flowerNames=['郁金香','雏菊','羽扇豆','绣球','向日葵','玫瑰','薰衣草','波斯菊','百合','三色堇','鸢尾','木槿'];
const flowerFiles=['tulip','daisy','lupine','hydrangea','sunflower','rose','lavender','cosmos','lily','pansy','iris','hibiscus'];
const el=id=>document.getElementById(id);
const state={stage:'input',title:'点外卖',delay:3,interval:5,flower:0,utterance:'待会儿记得提醒我点外卖',end:'',timer:null};
const flowerSrc=i=>assetRoot+'garden_flower_'+flowerFiles[i]+'.png';
function drawFlowers(root){root.innerHTML='<div class="flower-heading"><h2>选一朵喜欢的花</h2><span>12 种 · 左右滑动</span></div><div class="flower-rail"></div><p class="flower-note">完成赚水滴，再来浇花。7 滴水，就能开花。</p>';const rail=root.querySelector('.flower-rail');flowerNames.forEach((name,i)=>{const button=document.createElement('button');button.className='flower';button.dataset.flower=String(i);button.setAttribute('aria-pressed',String(i===state.flower));button.setAttribute('aria-label',name);const image=document.createElement('img');image.src=flowerSrc(i);image.alt='';const label=document.createElement('span');label.textContent=name;button.append(image,label);button.addEventListener('click',()=>{state.flower=i;refreshFlowers();});rail.append(button);});}
function refreshFlowers(){document.querySelectorAll('[data-flower]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.flower)===state.flower)));el('selected-flower').src=flowerSrc(state.flower);el('selected-flower').alt=flowerNames[state.flower];el('flower-copy').textContent='这次种'+flowerNames[state.flower];}
function exactDate(){return new Date(Date.now()+state.delay*60000);}
function formatted(date){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(date);}
function updateProposal(){el('time-link').firstChild.textContent=state.delay+' 分钟后';el('task-copy').textContent=state.title;el('task-name').value=state.title;el('follow-copy').textContent=state.interval?`还没完成，就每 ${state.interval} 分钟提醒你。\n做完就停${state.end?'，最晚到 '+state.end.replace('T',' '):''}。`:'只提醒这一次，之后不再催你。';el('follow-copy').style.whiteSpace='pre-line';el('original-copy').textContent='你说：'+state.utterance;el('exact-time').textContent='预计 '+formatted(exactDate())+' 首次提醒；从确认时起算 '+state.delay+' 分钟。时区 Asia/Shanghai。';el('delay-options').replaceChildren();[3,5,10,30].forEach(delay=>{const button=document.createElement('button');button.textContent=delay+' 分钟后';button.setAttribute('aria-pressed',String(state.delay===delay));button.addEventListener('click',()=>{state.delay=delay;el('time-choices').hidden=true;el('time-link').setAttribute('aria-expanded','false');updateProposal();});el('delay-options').append(button);});}
function show(stage){state.stage=stage;el('garden-app').dataset.stage=stage;['input','thinking','proposal','success'].forEach(name=>el(name+'-stage').hidden=name!==stage);el('confirm-footer').hidden=stage!=='proposal';el('subtitle').textContent={input:'把要记住的事，交给念念',thinking:'这件小事，我听见了。',proposal:'好，我来帮你记着。',success:'这件小事，我们说定了。'}[stage];el('arrange').disabled=stage==='thinking';if(stage==='proposal')updateProposal();}
function back(){clearTimeout(state.timer);show('input');el('wish').value=state.utterance;el('input-error').textContent='';}
function arrange(manual=false){const wish=el('wish').value.trim();if(!wish&&!manual){el('input-error').textContent='先告诉念念，要记住什么事。';return;}const match=wish.match(/提醒我\s*(.+?)(?:[，,。]|$)/);const title=match?match[1].trim():'';if(!manual&&!title){el('input-error').textContent='这是本地样稿，试试“3分钟后提醒我收衣服”或“待会儿提醒我点外卖”。';return;}const delay=wish.match(/(\d+)\s*分钟后/);if(delay&&(Number(delay[1])<1||Number(delay[1])>1440)){el('input-error').textContent='样稿支持 1 到 1440 分钟后。';return;}state.utterance=wish||'手动填写一件小事';state.title=title||'这件小事';if(delay)state.delay=Number(delay[1]);el('input-error').textContent='';if(manual){show('proposal');el('plan-details').open=true;el('task-name').focus();return;}show('thinking');state.timer=setTimeout(()=>{show('proposal');},850);}
el('arrange').addEventListener('click',()=>arrange());el('manual').addEventListener('click',()=>arrange(true));el('back').addEventListener('click',()=>{if(state.stage==='input'){window.location.href='a-fusion.html';}else back();});el('resay').addEventListener('click',()=>{back();el('wish').focus();});el('restart').addEventListener('click',back);
el('time-link').addEventListener('click',()=>{const visible=el('time-choices').hidden;el('time-choices').hidden=!visible;el('time-link').setAttribute('aria-expanded',String(visible));});
el('task-name').addEventListener('change',event=>{const value=event.target.value.trim();if(value)state.title=value;updateProposal();});el('follow-rule').addEventListener('change',event=>{state.interval=Number(event.target.value);updateProposal();});el('end-time').addEventListener('change',event=>{state.end=event.target.value;updateProposal();});
el('confirm').addEventListener('click',()=>{if(state.end&&new Date(state.end+'+08:00').getTime()<=exactDate().getTime()){el('detail-error').textContent='截止时间要晚于首次提醒。';el('plan-details').open=true;el('end-time').focus();return;}el('detail-error').textContent='';el('success-copy').textContent=formatted(exactDate())+'，提醒你'+state.title+'。';show('success');});
document.addEventListener('visibilitychange',()=>{el('seed').style.animationPlayState=document.hidden?'paused':'running';});
drawFlowers(el('initial-flowers'));drawFlowers(el('proposal-flowers'));refreshFlowers();show(new URLSearchParams(location.search).get('stage')==='proposal'?'proposal':'input');
